  {category: "Jun", value: 95}
];

const margin = {top: 60, right: 40, bottom: 60, left: 60};
const width = 800 - margin.left - margin.right;
const height = 500 - margin.top - margin.bottom;

d3.select("body")
  .style("background-color", "#f8f9fa")
  .style("font-family", "system-ui, -apple-system, sans-serif")
  .style("margin", "0")
  .style("padding", "40px 20px");

const container = d3.select("body")
  .append("div")
  .style("max-width", "880px")
  .style("margin", "0 auto")
  .style("background", "#ffffff")
  .style("border-radius", "12px")
  .style("box-shadow", "0 4px 20px rgba(0,0,0,0.08)")
  .style("padding", "24px");

const svg = container
  .append("svg")
  .attr("width", width + margin.left + margin.right)
  .attr("height", height + margin.top + margin.bottom)
  .append("g")
  .attr("transform", `translate(${margin.left},${margin.top})`);

svg.append("text")
  .attr("x", width / 2)
  .attr("y", -30)
  .attr("text-anchor", "middle")
  .style("font-size", "20px")
  .style("font-weight", "600")
  .style("fill", "#1f2937")
  .style("letter-spacing", "-0.5px")
  .text("Monthly Performance Overview");

const x = d3.scaleBand()
  .domain(data.map(d => d.category))
  .range([0, width])
  .padding(0.35);

const y = d3.scaleLinear()
  .domain([0, 100])
  .range([height, 0]);

svg.append("g")
  .attr("class", "grid")
  .call(d3.axisLeft(y)
    .tickSize(-width)
    .tickFormat("")
    .ticks(5)
  )
  .selectAll("line")
  .style("stroke", "#e5e7eb")
  .style("stroke-width", 1);

svg.select(".grid").select(".domain").remove();

const xAxis = svg.append("g")
  .attr("transform", `translate(0,${height})`)
  .call(d3.axisBottom(x).tickSize(0).tickPadding(15));

xAxis.select(".domain").style("stroke", "#e5e7eb");
xAxis.selectAll("text")
  .style("font-size", "14px")
  .style("fill", "#4b5563")
  .style("font-weight", "500");

const yAxis = svg.append("g")
  .call(d3.axisLeft(y).ticks(5).tickSize(0).tickPadding(10));

yAxis.select(".domain").remove();
yAxis.selectAll("text")
  .style("font-size", "13px")
  .style("fill", "#6b7280");

const bars = svg.selectAll(".bar")
  .data(data)
  .enter()
  .append("rect")
  .attr("class", "bar")
  .attr("x", d => x(d.category))
  .attr("width", x.bandwidth())
  .attr("y", height)
  .attr("height", 0)
  .attr("rx", 6)
  .attr("ry", 6)
  .attr("fill", "#3b82f6")
  .style("cursor", "pointer");

bars.transition()
  .duration(1200)
  .delay((d, i) => i * 120)
  .ease(d3.easeCubicOut)
  .attr("y", d => y(d.value))
  .attr("height", d => height - y(d.value));

