    .style("display", "flex")
    .style("justify-content", "center")
    .style("align-items", "center")
    .style("margin", "0")
    .style("padding", "20px")
    .style("box-sizing", "border-box");

  // Dimensions
  const margin = {top: 60, right: 40, bottom: 60, left: 80};
  const width = 800 - margin.left - margin.right;
  const height = 500 - margin.top - margin.bottom;

  // Create SVG
  const svg = container.append("svg")
    .attr("width", width + margin.left + margin.right)
    .attr("height", height + margin.top + margin.bottom)
    .style("background", "#ffffff")
    .style("border-radius", "12px")
    .style("box-shadow", "0 4px 20px rgba(0,0,0,0.08)");

  const g = svg.append("g")
    .attr("transform", `translate(${margin.left},${margin.top})`);

  // Sample data
  const data = [
    {name: "Product A", value: 65},
    {name: "Product B", value: 89},
    {name: "Product C", value: 45},
    {name: "Product D", value: 72},
    {name: "Product E", value: 94},
    {name: "Product F", value: 58}
  ];

  // Scales
  const x = d3.scaleBand()
    .domain(data.map(d => d.name))
    .range([0, width])
    .padding(0.35);

  const y = d3.scaleLinear()
    .domain([0, 100])
    .range([height, 0]);

  // Define gradient
  const defs = svg.append("defs");
  const gradient = defs.append("linearGradient")
    .attr("id", "barGradient")
    .attr("x1", "0%")
    .attr("y1", "100%")
    .attr("x2", "0%")
    .attr("y2", "0%");

  gradient.append("stop")
    .attr("offset", "0%")
    .attr("stop-color", "#5e92f3");

  gradient.append("stop")
    .attr("offset", "100%")
    .attr("stop-color", "#1565c0");

  // Grid lines
  const yAxisGrid = d3.axisLeft(y)
    .tickSize(-width)
    .tickFormat("")
    .ticks(5);

  g.append("g")
    .attr("class", "grid")
    .call(yAxisGrid)
    .style("stroke", "#e0e0e0")
    .style("stroke-dasharray", "3,3")
    .selectAll("line")
    .style("stroke-opacity", 0.7);

  g.select(".grid").select(".domain").remove();

  // Axes
  const xAxis = g.append("g")
    .attr("transform", `translate(0,${height})`)
    .call(d3.axisBottom(x).tickSize(0))
    .style("font-size", "13px")
    .style("font-weight", "500")
    .style("color", "#424242");

  xAxis.select(".domain").style("stroke", "#bdbdbd");
  xAxis.selectAll("text")
    .style("fill", "#424242")
    .attr("dy", "1.5em");

  const yAxis = g.append("g")
    .call(d3.axisLeft(y).ticks(5).tickSize(0))
    .style("font-size", "12px")
    .style("color", "#616161");

  yAxis.select(".domain").style("stroke", "#bdbdbd");
  yAxis.selectAll("text").style("fill", "#616161").attr("dx", "-0.5em");

  // Title
  svg.append("text")
    .attr("x", (width + margin.left + margin.right) / 2)
    .attr("y", 35)
    .attr("text-anchor", "middle")
    .style("font-size", "20px")
    .style("font-weight", "600")
    .style("fill", "#212121")
    .style("letter-spacing", "-0.5px")
    .text("Quarterly Performance");

  // Bars
  const bars = g.selectAll(".bar")
    .data(data)
    .enter()
    .append("rect")
    .attr("class", "bar")
    .attr("x", d => x(d.name))
    .attr("width", x.bandwidth())
    .attr("y", height)
    .attr("height", 0)
    .attr("rx", 6)
    .attr("ry", 6)
    .style("fill", "url(#barGradient)")
    .style("cursor", "pointer")
    .style("filter", "drop-shadow(0 2px 4px rgba(21,101,192,0.2))");

  // Animate bars
  bars.transition()
    .duration(1200)
    .delay((d, i) => i * 150)
    .ease(d3.easeBackOut.overshoot(0.3))
    .attr("y", d => y(d.value))
    .attr("height", d => height - y(d.value));

  // Value labels
  const labels = g.selectAll(".label")
    .data(data)
    .enter()
    .append("text")
    .attr("class", "label")
    .attr("x", d => x(d.name) + x.bandwidth() / 2)
    .attr("y", height)
    .attr("text-anchor", "middle")
    .style("font-size", "13px")
    .style("font-weight", "600")
    .style("fill", "#1565c0")
    .style("opacity", 0)
    .text(d => d.value + "%");

  labels.transition()
    .duration(1200)
    .delay((d, i) => i * 150 + 400)
    .ease(d3.easeCubicOut)
    .attr("y", d => y(d.value) - 8)
    .style("opacity", 1);

  // Interactions
  bars.on("mouseenter", function(event, d) {
    d3.select(this)
      .transition()
      .duration(200)
      .style("fill", "#0d47a1")
      .style("filter", "drop-shadow(0 4px 8px rgba(13,71,161,0.3))");
  })
  .on("mouseleave", function() {
    d3.select(this)
      .transition()
      .duration(200)
      .style("fill", "url(#barGradient)")
      .style("filter", "drop-shadow(0 2px 4px rgba(21,101,192,0.2))");
  });

  // Subtitle
  svg.append("text")
    .attr("x", (width + margin.left + margin.right) / 2)
    .attr("y", 55)
    .attr("text-anchor", "middle")
    .style("font-size", "14px")
    .style("fill", "#757575")
    .text("2024 Sales Metrics by Category");
})();

